(()=>{
  const $=id=>document.getElementById(id),data=$('botProductData');if(!data)return;const products=JSON.parse(data.textContent),byId=Object.fromEntries(products.map(p=>[p.id,p]));
  const storageKey='wildSeedClubBasket';let basket={};try{basket=JSON.parse(sessionStorage.getItem(storageKey)||'{}')}catch{basket={}};
  const drawer=$('botDrawer'),modal=$('botProductModal'),cartItems=$('botCartItems'),cartTotal=$('botCartTotal'),bagCount=$('botBagCount'),cartMessage=$('botCartMessage');let activeProduct=null,lastFocused=null;
  const save=()=>{try{sessionStorage.setItem(storageKey,JSON.stringify(basket))}catch{}};
  const count=()=>Object.values(basket).reduce((a,b)=>a+b,0);
  const money=v=>'$'+v.toFixed(2);
  function renderCart(){bagCount.textContent=count();cartItems.replaceChildren();const ids=Object.keys(basket).filter(id=>basket[id]>0&&byId[id]);if(!ids.length){const p=document.createElement('p');p.textContent='Nothing planted. Yet. Explore the seed shop and collect your favorite imaginary packets.';cartItems.append(p)}let total=0;ids.forEach(id=>{const product=byId[id],q=basket[id];total+=product.price*q;const item=document.createElement('div');item.className='bot-cart-item';const copy=document.createElement('div'),name=document.createElement('strong'),price=document.createElement('span');name.textContent=product.name;price.textContent='  '+money(product.price*q);copy.append(name,document.createElement('br'),price);const controls=document.createElement('div');controls.className='bot-cart-controls';for(const [text,change] of [['−',-1],['+',1]]){const btn=document.createElement('button');btn.type='button';btn.textContent=text;btn.setAttribute('aria-label',(change>0?'Add':'Remove')+' one '+product.name);btn.onclick=()=>{basket[id]=Math.max(0,(basket[id]||0)+change);if(!basket[id])delete basket[id];save();renderCart()};controls.append(btn)}const qLabel=document.createElement('span');qLabel.textContent=q;controls.insertBefore(qLabel,controls.lastChild);item.append(copy,controls);cartItems.append(item)});cartTotal.textContent=money(total)}
  function closeDrawer(){drawer.hidden=true;document.body.style.overflow='';lastFocused?.focus()};
  function openDrawer(origin){lastFocused=origin||document.activeElement;renderCart();drawer.hidden=false;document.body.style.overflow='hidden';$('botClose').focus()};
  function add(id){basket[id]=(basket[id]||0)+1;save();renderCart();cartMessage.textContent='Added to your imaginary garden. No real order was placed.'};
  $('botBag').addEventListener('click',e=>openDrawer(e.currentTarget));$('botShopBag')?.addEventListener('click',e=>openDrawer(e.currentTarget));$('botClose').addEventListener('click',closeDrawer);$('botDrawerShade').addEventListener('click',closeDrawer);
  $('botPreview').addEventListener('click',()=>{const chosen=Object.entries(basket).filter(([,q])=>q>0).map(([id,q])=>q+' × '+byId[id]?.name);cartMessage.textContent=chosen.length?'Your imaginary garden: '+chosen.join(', ')+'. A concept preview only—nothing purchased or saved to a server.':'Choose a seed packet before previewing your imaginary garden.'});
  document.querySelectorAll('[data-add]').forEach(btn=>btn.addEventListener('click',()=>{add(btn.dataset.add);openDrawer(btn)}));
  const openDetails=(id,origin)=>{const p=byId[id];if(!p)return;activeProduct=id;lastFocused=origin;$('botProductTitle').textContent=p.name;$('botProductDescription').textContent=p.details;$('botProductGrow').textContent=p.grow;modal.hidden=false;document.body.style.overflow='hidden';$('botProductClose').focus()};
  const closeDetails=()=>{modal.hidden=true;document.body.style.overflow='';lastFocused?.focus()};
  document.querySelectorAll('[data-details]').forEach(btn=>btn.addEventListener('click',()=>openDetails(btn.dataset.details,btn)));
  $('botProductClose').addEventListener('click',closeDetails);$('botProductShade').addEventListener('click',closeDetails);$('botProductAdd').addEventListener('click',()=>{if(activeProduct)add(activeProduct);closeDetails();openDrawer(lastFocused)});
  document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(!modal.hidden)closeDetails();else if(!drawer.hidden)closeDrawer()});
  document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{const value=btn.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{const current=x===btn;x.classList.toggle('active',current);x.setAttribute('aria-pressed',String(current))});document.querySelectorAll('[data-category]').forEach(card=>card.hidden=value!=='All'&&card.dataset.category!==value)}));
  renderCart();
})();
